5. Erstellen Sie eine neue Datei namens `cypress/plugins/index.js`:

```javascript
const { addPlugin } = require('cypress');

module.exports = (on) => {
  on('task', {
    screenshot: ({ testName, fullPage }) => {
      return Cypress.runner.run(() => {
        const browser = Cypress.browser;
