Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes zählt:

```c++
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string wordToCount;
    int count = 0;

    // Wort, nach dem gezählt werden soll, von Benutzer einlesen
    cout << "Geben Sie das Wort ein, nach dem gezählt werden soll: ";
    cin >> wordToCount;

    // Dateiöffnen und Lesen
    string fileName;
    cout << "Geben Sie den Dateinamen ein: ";
    cin >> fileName;

    ifstream inputFile(fileName);

    if (!inputFile) {
        cerr << "Fehler: Datei konnte nicht geöffnet werden!" << endl;
        return 1;
    }

    string currentLine;
    while (getline(inputFile, currentLine)) {
        // Wort in Kleinbuchstaben umwandeln und in Vektoren aufteilen
        transform(currentLine.begin(), currentLine.end(), currentLine.begin(), ::tolower);
        vector<string> words;
        size_t pos = 0;
        string token;
        while ((pos = currentLine.find(" ")) != string::npos) {
            token = currentLine.substr(pos, currentLine.find(" ", pos + 1) - pos);
            words.push_back(token);
            pos += token.length() + 1;
        }
        words.push_back(currentLine.substr(pos));

        // Wort zählen
        for (const auto& w : words) {
            if (w == wordToCount) {
                count++;
            }
        }
    }

    inputFile.close();

    // Ergebnis ausgeben
    cout << "Das Wort '" << wordToCount << "' tritt " << count << " mal in der Datei '" << fileName << "' auf." << endl;

    return 0;
}
```

Dieses Programm erfordert die folgenden Schritte:

1. Es fragt den Benutzer nach dem Wort, nach dem gezählt werden soll.
2. Es fragt den Benutzer nach dem Dateinamen, in dem gesucht werden soll.
3. Es öffnet die Datei und liest sie Zeile für Zeile ein.
4. Für jede Zeile:
   a. Wandelt sie in Kleinbuchstaben um.
   b. Teilt sie in Wörter auf, die durch Leerzeichen getrennt sind.
   c. Zählt das gesuchte Wort in der aktuellen Zeile.
5. Schließt die Datei.
6. Gibt das Ergebnis aus.

